node -e "
const ExcelJS = require('exceljs');

(async () => {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Extracted Text');

  // Header row
  sheet.columns = [
    { header: 'Line', key: 'line', width: 10 },
    { header: 'Extracted Text', key: 'text', width: 60 }
  ];

  // Style header
  sheet.getRow(1).font = { bold: true };

  // Read extracted text and add non-empty lines
  const fs = require('fs');
  const lines = fs.readFileSync('/workspace/handbook_text.txt', 'utf-8')
    .split('\n')
    .filter(l => l.trim() !== '');

  lines.forEach((text, i) => {
    sheet.addRow({ line: i + 1, text });
  });

  await workbook.xlsx.writeFile('/workspace/handbook_extracted.xlsx');
  console.log('Excel file created successfully.');
})();
"
